cd /tmp/sv-639894477c10421e84f7739ab50bd4aa && \
# Use objdump to find the function at these offsets
pip install pyelftools -q 2>/dev/null
python3 << 'EOF'
from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection

addrs = [0x222098, 0x2241ac, 0x1abc80, 0x16de04, 0x2f4b20, 0x2f4c84, 0x2c1a40]

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    symtab = elf.get_section_by_name('.symtab')
    if not symtab:
        symtab = elf.get_section_by_name('.dynsym')

    # Build sorted list of function symbols
    funcs = []
    for sym in symtab.iter_symbols():
        if sym['st_info']['type'] in ('STT_FUNC', 'STT_NOTYPE') and sym['st_value'] > 0 and sym['st_size'] > 0:
            funcs.append((sym['st_value'], sym['st_size'], sym.name))

    funcs.sort()

    for addr in addrs:
        found = None
        for val, size, name in funcs:
            if val <= addr < val + size:
                found = (name, addr - val)
                break
        if found:
            print(f"0x{addr:x}: {found[0]}+0x{found[1]:x}")
        else:
            # Binary search for nearest lower
            lo, hi = 0, len(funcs) - 1
            while lo <= hi:
                mid = (lo + hi) // 2
                if funcs[mid][0] <= addr:
                    lo = mid + 1
                else:
                    hi = mid - 1
            if hi >= 0:
                val, size, name = funcs[hi]
                print(f"0x{addr:x}: ~{name}+0x{addr-val:x} (outside declared size)")
            else:
                print(f"0x{addr:x}: ???")
EOF

