arguments.command:
cd /tmp/sv-639894477c10421e84f7739ab50bd4aa && \
# The Cortex-A53 erratum thunks are trampolines - let's look at what function these really belong to
# Try using DWARF info directly for line info
python3 << 'EOF'
from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

addrs = [0x2f4b20, 0x2f4c84, 0x2c1a40]

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    if not elf.has_dwarf_info():
        print("No DWARF info!")
        exit(1)

    dwarf = elf.get_dwarf_info()

    # Use line program to find source info
    for CU in dwarf.iter_CUs():
        lp = dwarf.line_program_for_CU(CU)
        if lp is None:
            continue
        prev_state = None
        for entry in lp.get_entries():
            if entry.state is None:
                continue
            state = entry.state
            if prev_state:
                for addr in addrs[:]:
                    if prev_state.address <= addr < state.address:
                        file_entry = lp['file_entry'][prev_state.file - 1]
                        dir_idx = file_entry['dir_index']
                        if dir_idx > 0:
                            dir_name = lp['include_directory'][dir_idx - 1].decode() if isinstance(lp['include_directory'][dir_idx - 1], bytes) else str(lp['include_directory'][dir_idx - 1])
                        else:
                            dir_name = ''
                        fname = file_entry.name.decode() if isinstance(file_entry.name, bytes) else str(file_entry.name)
                        print(f"0x{addr:x}: {dir_name}/{fname}:{prev_state.line}")
                        addrs.remove(addr)
            prev_state = state
            if state.end_sequence:
                prev_state = None
        if not addrs:
            break

    for addr in addrs:
        print(f"0x{addr:x}: no DWARF line info found")
EOF

